package com.example.petadoptioncommunity.shop;
import org.springframework.stereotype.Service;import com.example.petadoptioncommunity.identity.*;import com.example.petadoptioncommunity.web.*;import static com.example.petadoptioncommunity.web.Values.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
@Service public class ShopService {
 private final ShopMapper db;private final IdentityService identity;
 public ShopService(ShopMapper db,IdentityService identity){this.db=db;this.identity=identity;}
 public record ProductInput(String name,String category,String description,String image,Long price,Integer stock,Boolean listed,Boolean recommended,Long version){}
 public record AddressInput(String recipient,String phone,String address,Long version){}
 public record Checkout(String addressId,String quoteToken,String operationId){}
 private String digest(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private List<Map<String,Object>> cartRows(String id){return db.cart(id).stream().map(Values::row).toList();}
 public Object catalog(String keyword,String category,int page,boolean management,IdentityPort.Actor a){if(page<1||page>100000)throw bad("页码无效");if(management)admin(a);String k=text(keyword,100,false).toLowerCase(Locale.ROOT);var all=db.products().stream().map(Values::row).sorted(Comparator.comparing((Map<String,Object> p)->!bool(p,"recommended"))).filter(p->(management||bool(p,"listed"))&&p.get("name").toString().toLowerCase(Locale.ROOT).contains(k)&&(category==null||category.isBlank()||category.equals(p.get("category")))).toList();return Map.of("items",all.stream().skip((long)(page-1)*12).limit(12).toList(),"total",all.size(),"categories",db.products().stream().map(Values::row).filter(p->management||bool(p,"listed")).map(p->p.get("category")).distinct().sorted((x,y)->x.toString().compareTo(y.toString())).toList());}
 public Object detail(String id){uuid(id);var p=row(db.product(id));if(!bool(p,"listed"))throw missing();return p;}
 public Object saveProduct(IdentityPort.Actor a,String id,ProductInput v){admin(a);String name=text(v.name,100,true),category=text(v.category,40,true),description=text(v.description,1000,false),image=image(v.image);if(v.price==null||v.price<=0||v.price>100000000||v.stock==null||v.stock<0||v.listed==null||v.recommended==null)throw bad("请检查价格和库存");return identity.withActiveActor(a,List.of(),()->{Map<String,Object> p=new HashMap<>(Map.of("id",id==null?UUID.randomUUID().toString():id,"name",name,"category",category,"description",description,"image",image,"price",v.price,"stock",v.stock,"listed",v.listed,"recommended",v.recommended));if(id==null)db.insertProduct(p);else{uuid(id);row(db.lockProduct(id));if(v.version==null||v.version<0)throw bad("缺少版本");p.put("version",v.version);if(db.updateProduct(p)!=1)throw conflict("商品已变更，请刷新后重新编辑");}org.slf4j.LoggerFactory.getLogger(getClass()).info("ADMIN_PRODUCT actor={} target={}",a.userId(),p.get("id"));return row(db.product((String)p.get("id")));});}
 public Object cart(IdentityPort.Actor a){return identity.withActiveActor(a,List.of(),()->Map.of("items",cartRows(a.userId())));}
 public Object setCart(IdentityPort.Actor a,String id,Integer quantity,Boolean selected,boolean add){uuid(id);if(quantity==null||quantity<1||quantity>100000||selected==null)throw bad("数量必须为正整数");return identity.withActiveActor(a,List.of(),()->{var p=row(db.product(id));int q=quantity;if(add){for(var c:cartRows(a.userId()))if(id.equals(c.get("productId")))q=Math.addExact(q,((Number)c.get("quantity")).intValue());}if(!bool(p,"listed")||q>number(p,"stock"))throw conflict("商品已下架或库存不足");db.cartSet(a.userId(),id,q,selected);return Map.of("items",cartRows(a.userId()));});}
 public Object deleteCart(IdentityPort.Actor a,String id){uuid(id);return identity.withActiveActor(a,List.of(),()->{db.cartDelete(a.userId(),id);return Map.of("items",cartRows(a.userId()));});}
 public Object addresses(IdentityPort.Actor a){return identity.withActiveActor(a,List.of(),()->db.addresses(a.userId()).stream().map(Values::row).toList());}
 public Object saveAddress(IdentityPort.Actor a,String id,AddressInput v){String name=text(v.recipient,50,true),phone=text(v.phone,32,true),address=text(v.address,300,true);return identity.withActiveActor(a,List.of(),()->{var p=new HashMap<String,Object>(Map.of("id",id==null?UUID.randomUUID().toString():id,"userId",a.userId(),"recipient",name,"phone",phone,"address",address));if(id==null)db.insertAddress(p);else{uuid(id);var old=row(db.address(id));if(!a.userId().equals(old.get("userId")))throw new ApiFailure(403,"FORBIDDEN","无权修改此地址");if(v.version==null||v.version<0)throw bad("缺少版本");p.put("version",v.version);if(db.updateAddress(p)!=1)throw conflict("地址已变更，请刷新");}return row(db.address((String)p.get("id")));});}
 private Map<String,Object> quote(String userId,String addressId){var lines=cartRows(userId).stream().filter(c->bool(c,"selected")).toList();if(lines.isEmpty())throw bad("请选择结算商品");var addr=row(db.address(addressId));if(!userId.equals(addr.get("userId")))throw new ApiFailure(403,"FORBIDDEN","无权使用此地址");long total=0;StringBuilder signature=new StringBuilder(addressId+":"+addr.get("version"));for(var c:lines){if(!bool(c,"listed")||number(c,"quantity")>number(c,"stock"))throw conflict("商品已下架或库存不足："+c.get("name"));total=Math.addExact(total,Math.multiplyExact(number(c,"price"),number(c,"quantity")));signature.append('|').append(c.get("productId")).append(':').append(c.get("quantity")).append(':').append(c.get("price")).append(':').append(c.get("productVersion"));}var q=new LinkedHashMap<String,Object>();q.putAll(Pricing.calculate(total));q.put("items",lines);q.put("address",addr);q.put("quoteToken",digest(signature.toString()));return q;}
 public Object getQuote(IdentityPort.Actor a,String addressId){uuid(addressId);return identity.withActiveActor(a,List.of(),()->quote(a.userId(),addressId));}
 public Object create(IdentityPort.Actor a,Checkout v){uuid(v.addressId);uuid(v.operationId);if(v.quoteToken==null||!v.quoteToken.matches("[a-f0-9]{64}"))throw bad("请先核对报价");String fingerprint=digest(v.addressId+":"+v.quoteToken);return identity.withActiveActor(a,List.of(),()->{var old=db.operation(a.userId(),v.operationId);if(old!=null){var o=row(old);if(!fingerprint.equals(o.get("fingerprint")))throw conflict("同一操作标识不能使用不同内容");return view(o,a);}
 var selected=cartRows(a.userId()).stream().filter(c->bool(c,"selected")).toList();for(var c:selected)db.lockProduct((String)c.get("productId"));var q=quote(a.userId(),v.addressId);if(!v.quoteToken.equals(q.get("quoteToken")))throw conflict("商品或地址已变化，请重新确认报价");var addr=(Map<String,Object>)q.get("address");var o=new HashMap<String,Object>(q);o.putAll(Map.of("id",UUID.randomUUID().toString(),"userId",a.userId(),"operationId",v.operationId,"fingerprint",fingerprint,"recipient",addr.get("recipient"),"phone",addr.get("phone"),"address",addr.get("address")));db.insertOrder(o);for(var c:selected){var item=new HashMap<String,Object>(c);item.put("orderId",o.get("id"));db.insertItem(item);db.cartDelete(a.userId(),(String)c.get("productId"));}return view(row(db.order((String)o.get("id"))),a);});}
 private Map<String,Object> view(Map<String,Object> o,IdentityPort.Actor a){if(!a.userId().equals(o.get("userId"))&&!"ADMIN".equals(a.role()))throw new ApiFailure(403,"FORBIDDEN","无权查看订单");o.remove("fingerprint");o.remove("operationId");o.put("items",db.items((String)o.get("id")).stream().map(Values::row).toList());if(!a.userId().equals(o.get("userId"))&&Set.of("PENDING","CANCELLED").contains(o.get("status"))){o.remove("recipient");o.remove("phone");o.remove("address");}return o;}
 public Object orders(IdentityPort.Actor a,boolean all){if(all)admin(a);return identity.withActiveActor(a,List.of(),()->(all?db.allOrders():db.orders(a.userId())).stream().map(Values::row).map(o->view(o,a)).toList());}
 public Object order(IdentityPort.Actor a,String id){uuid(id);return identity.withActiveActor(a,List.of(),()->view(row(db.order(id)),a));}
 public Object action(IdentityPort.Actor a,String id,String action,String carrier,String tracking,boolean success){uuid(id);if(!Set.of("pay","cancel","ship","receive").contains(action))throw bad("订单操作无效");return identity.withActiveActor(a,List.of(),()->{var o=row(db.lockOrder(id));boolean owner=a.userId().equals(o.get("userId"));if(action.equals("ship"))admin(a);else if(!owner)throw new ApiFailure(403,"FORBIDDEN","仅订单本人可操作");String status=(String)o.get("status");if(action.equals("pay")){if(Set.of("PAID","SHIPPED","COMPLETED").contains(status))return view(o,a);if(!status.equals("PENDING"))throw conflict("当前订单不能付款");if(success){var items=db.items(id).stream().map(Values::row).toList();for(var item:items){var p=row(db.lockProduct((String)item.get("productId")));if(!bool(p,"listed")||number(p,"stock")<number(item,"quantity"))throw conflict("库存不足或已下架："+item.get("name"));}for(var item:items)if(db.deduct((String)item.get("productId"),((Number)item.get("quantity")).intValue())!=1)throw conflict("库存不足");db.orderState(id,"PAID");}}
 else if(action.equals("cancel")){if(!status.equals("CANCELLED")){if(!status.equals("PENDING"))throw conflict("仅待付款可取消");db.orderState(id,"CANCELLED");}}
 else if(action.equals("ship")){if(!status.equals("PAID"))throw conflict("仅待发货可发货");db.ship(id,text(carrier,50,true),text(tracking,80,true));org.slf4j.LoggerFactory.getLogger(getClass()).info("ADMIN_SHIP actor={} order={}",a.userId(),id);}
 else if(!status.equals("COMPLETED")){if(!status.equals("SHIPPED"))throw conflict("仅已发货可确认收货");db.orderState(id,"COMPLETED");}return view(row(db.order(id)),a);});}
}
